/* Ironlog — the exercise picker: search, recent lifts, groups by body part,
   kit at this place, what is still tired. One sheet used by Train, the planner,
   events and import review. Split out of workout.js (ROADMAP E17 phase 5). */
/* imports — generated by r&d/tools/module-map.cjs --sync, not by hand */
import { $, esc, wt } from './core.js';
import { save } from './database.js';
import { EQ_ICON, EQ_TITLE, allExercises, categoryOf, completeLeaf, ensureCustomMovement, exKey, exName, keyLeaf,
  movementById, variantLabel } from './exercises.js';
import { closeModal, modal, toast } from './kit.js';
import { curPlace, kitHas, leafHere, movableHere, placeName, placeSwap } from './loading.js';
import { S } from './state.js';
import { fatigueDot, fatigueMap, fatigueSummary, leafFatigue, statsFor } from './stats.js';
/* end imports */

/* ---------------- the exercise picker ---------------- */
/* ---------------- exercise picker ---------------- */
export function pickExercise(cb) {
  const seenRecent = new Set();
  const recent = S.workouts.filter(w => w.status === 'completed').slice(-12).reverse()
    .flatMap(w => w.exercises.filter(e => e.leaf).map(e => ({ key: exKey(e), leaf: e.leaf, name: exName(e) })))
    .filter(x => !seenRecent.has(x.key) && seenRecent.add(x.key)).slice(0, 8);
  const fm = fatigueMap();
  const draw = (q) => {
    const all = allExercises();
    const ql = (q || '').toLowerCase();
    /* aliases count as a match too ("Klokov" finds Behind The Neck Press) — search only, never identity */
    const hits = x => x.name.toLowerCase().includes(ql)
      || ((movementById(x.leaf.movement) || {}).aliases || []).some(a => a.name.toLowerCase().includes(ql));
    const list = (ql ? all.filter(hits) : all).slice()
      .sort((x, y) => (movableHere(x.leaf) ? 0 : 1) - (movableHere(y.leaf) ? 0 : 1));   // stable: kit that isn't here sinks (D6)
    const groups = {};
    list.forEach(x => { const c = categoryOf(x.leaf); (groups[c] = groups[c] || []).push(x); });
    let html = curPlace() ? `<div class="sub" style="padding:4px 16px 2px">At ${esc(placeName())} — greyed needs kit that isn't here.</div>` : '';
    const fsum = fatigueSummary(fm);   // D7: what's still tired, so the pick can go elsewhere
    if (fsum && !q) html += `<div class="sub" style="padding:4px 16px 2px">${esc(fsum)}</div>`;
    if (!q && recent.length) {
      html += `<div style="padding:8px 16px 4px" class="eyebrow">Recent</div>`;
      html += recent.map(item).join('');
    }
    Object.entries(groups).forEach(([c, names]) => {
      html += `<div style="padding:10px 16px 4px" class="eyebrow">${c}</div>`;
      html += names.map(item).join('');
    });
    if (q && !list.length) html = `<div class="empty">No match. Create “${esc(q)}” below.</div>`;
    return html;
  };
  /* The name is the movement; the equipment is a separate axis. Showing the
     equipment a movement can be done with — as icons, on the row itself — is
     what makes that split legible: one "Lat Raise" that can be a cable or a
     dumbbell, rather than two rows spelling it out. The icons are tappable, so
     picking the variant is one gesture rather than add-then-change; a row of
     icons that looked tappable and was not would be worse than none. */
  const eqRow = x => {
    const m = movementById(x.leaf.movement);
    const opts = (m && m.equipment) || [];
    if (opts.length < 2) return '';
    return `<div class="eqrow">${opts.map(v => `<span class="eqi ${v === x.leaf.equipment ? 'on' : ''} ${kitHas(v) ? '' : 'na'}"
      data-pickeq="${esc(x.leaf.movement)}|${esc(v)}" title="${esc(EQ_TITLE[v] || v)}${kitHas(v) ? '' : ` — not at ${esc(placeName())}`}">${EQ_ICON[v] || ''}</span>`).join('')}</div>`;
  };

  const item = x => {
    const st = statsFor(x.key);
    const v = variantLabel(x.leaf);
    const meta = [v, st ? `PR ${wt(st.bestW.w)} × ${st.bestW.r} · ${st.sessions} sessions` : 'No history']
      .filter(Boolean).join(' · ');
    return `<div class="pickitem ${movableHere(x.leaf) ? '' : 'na'}" data-pick="${esc(x.key)}">
      <div class="grow"><div class="n">${fatigueDot(leafFatigue(x.leaf, fm))}${esc(x.name)}</div><div class="m">${esc(meta)}</div>${eqRow(x)}</div>
      <span class="dimmer">›</span></div>`;
  };
  modal({
    title: 'Add exercise',
    body: `<input id="pkQ" placeholder="Search or type a new exercise…" autocomplete="off">
           <div class="picklist" id="pkList" style="margin-top:12px">${draw('')}</div>`,
    foot: `<button class="btn ghost" data-close>Cancel</button><button class="btn" id="pkNew">Create new</button>`,
    onOpen: bg => {
      const list = $('#pkList', bg), q = $('#pkQ', bg);
      const bind = () => {
        list.querySelectorAll('[data-pick]').forEach(el =>
          el.onclick = () => { const lf = keyLeaf(el.dataset.pick); closeModal(); cb(leafHere(lf) ? lf : placeSwap(lf) || lf); });
        /* Bound after the row, and stops the event, so tapping an icon picks
           that equipment instead of the row's default leaf. */
        list.querySelectorAll('[data-pickeq]').forEach(el => el.onclick = ev => {
          ev.stopPropagation();
          const [movement, equipment] = el.dataset.pickeq.split('|');
          const m = movementById(movement);
          if (!m) return;
          if (!kitHas(equipment)) return toast(`${EQ_TITLE[equipment] || equipment} isn't at ${placeName()}`);
          closeModal();
          cb(completeLeaf(m, { equipment }));
        });
      };
      bind();
      q.oninput = () => { list.innerHTML = draw(q.value.trim()); bind(); };
      $('#pkNew', bg).onclick = () => {
        const name = q.value.trim();
        if (!name) return toast('Type a name first');
        /* A name the catalogue does not know becomes its own movement rather
           than being guessed into an existing one. */
        save(); closeModal(); cb(completeLeaf(ensureCustomMovement(name), null));
      };
      setTimeout(() => q.focus(), 60);
    },
  });
}
